// seed: tests/seed.parent-b.spec.ts
// «לראות את המידע» уходит без окна пароля. Сам запрос НЕ отправляется: запись обрывается в браузере.
// Если приложение само ответит «כבר יש בקשה כזו בטיפול» (у QA-B1 уже есть открытый запрос «עיון» bfff9a9e) — тоже ок.
import { test, expect } from '@playwright/test';
import { PARENT_B, T, blockDataRequestWrites, chip, openForm, sendButton, visibleText } from './data-requests.helpers';

test.use({ storageState: PARENT_B, viewport: { width: 1280, height: 800 } });

test.describe('Запросы данных — «עיון» без пароля', () => {
  test('«לראות את המידע»: отправка без окна «אימות זהות» @desktop @prod-safe #c3aa39', async ({ page }) => {
    const writes = await blockDataRequestWrites(page);
    await openForm(page);

    await chip(page, 'QA-B1').click();
    await chip(page, T.kindView).click();
    await sendButton(page).click();

    // Приложение пытается отправить сразу (запись перехвачена) или показывает ответ о существующем запросе
    const answer = page.getByText(T.sent).filter({ visible: true });
    await expect
      .poll(async () => writes.length > 0 || (await answer.count()) > 0, { message: 'отправка «עיון» без промежуточного окна' })
      .toBe(true);

    // Окна пароля нет
    await expect(visibleText(page, T.reauthTitle)).toHaveCount(0);
    await expect(page.locator('input[type="password"]').filter({ visible: true })).toHaveCount(0);

    // Перехваченная запись — не удаление
    for (const w of writes) expect(JSON.stringify(w.body), 'тип запроса не delete').not.toMatch(/"delete"|"family/);
  });
});
